"use client";
import Link from "next/link";
import { useEffect, useState } from "react";
import { ArrowRight, CalendarDays, Check, ChevronDown, Download, LogOut, Users } from "lucide-react";
import { clubs as demoClubs, type Club } from "@/lib/types";
import { createSupabaseBrowserClient } from "@/lib/supabase-browser";

function downloadCsv(clubs: Club[]) {
  const rows = [["Club", "Audience", "Meeting day", "Meeting time", "Members"], ...clubs.map((club) => [club.name, club.audience, club.meeting_day, club.meeting_time, String(club.members)])];
  const csv = rows.map((row) => row.map((cell) => `"${cell.replaceAll('"', '""')}"`).join(",")).join("\n");
  const url = URL.createObjectURL(new Blob([csv], { type: "text/csv" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "rusinga-club-members.csv"; anchor.click(); URL.revokeObjectURL(url);
}

export default function AdminPage() {
  const [name, setName] = useState("Club leader"); const [visibleClubs, setVisibleClubs] = useState<Club[]>(demoClubs);
  useEffect(() => { const supabase = createSupabaseBrowserClient(); if (supabase) { supabase.auth.getUser().then(({ data }) => setName(data.user?.email?.split("@")[0] || "Club leader")); supabase.from("clubs").select("*, registrations(id)").order("name").then(({ data }) => { if (data?.length) setVisibleClubs(data.map((club, index) => ({ ...club, color: demoClubs[index % demoClubs.length].color, icon: demoClubs[index % demoClubs.length].icon, members: club.registrations?.length || 0 }))); }); } }, []);
  const total = visibleClubs.reduce((sum, club) => sum + club.members, 0); const max = Math.max(1, ...visibleClubs.map((club) => club.members));
  async function signOut() { const supabase = createSupabaseBrowserClient(); if (supabase) await supabase.auth.signOut(); window.location.href = "/"; }
  return <main className="min-h-[calc(100vh-76px)] bg-[#f7fafc] px-5 py-10 sm:px-8 lg:px-10"><div className="mx-auto max-w-7xl"><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="text-[11px] font-bold uppercase tracking-[.2em] text-violet">Clubs hub / overview</p><h1 className="mt-3 text-3xl font-bold tracking-tight text-blue-950 sm:text-4xl">Good afternoon, {name}.</h1><p className="mt-2 text-sm text-slate-500">Here&apos;s what&apos;s happening across clubs this term.</p></div><div className="flex flex-wrap gap-2"><Link href="/admin/requests" className="rounded-xl border border-slate-200 bg-white px-4 py-3 text-xs font-bold text-violet transition hover:border-violet">Change requests</Link><Link href="/admin/manage" className="rounded-xl border border-slate-200 bg-white px-4 py-3 text-xs font-bold text-blue-900 transition hover:border-silver">Manage clubs</Link><button onClick={() => downloadCsv(visibleClubs)} className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-3 text-xs font-bold text-blue-900 transition hover:border-silver"><Download size={15} /> Export CSV</button><button onClick={signOut} className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-3 text-xs font-bold text-slate-500 transition hover:text-orange"><LogOut size={15} /></button></div></div><div className="mt-9 grid gap-4 sm:grid-cols-3"><div className="rounded-2xl bg-blue-900 p-5 text-white shadow-card"><div className="flex items-center justify-between"><span className="text-[11px] font-semibold text-white/60">Total registrations</span><Users size={17} className="text-bumblebee" /></div><p className="mt-5 text-4xl font-bold">{total}</p><p className="mt-1 text-[11px] text-white/50">Across all active clubs</p></div><div className="rounded-2xl border border-slate-100 bg-white p-5 shadow-card"><div className="flex items-center justify-between"><span className="text-[11px] font-semibold text-slate-400">Active clubs</span><span className="text-lg text-violet">✦</span></div><p className="mt-5 text-4xl font-bold text-blue-950">{visibleClubs.length}</p><p className="mt-1 text-[11px] text-slate-400">Registration choices open</p></div><div className="rounded-2xl border border-slate-100 bg-white p-5 shadow-card"><div className="flex items-center justify-between"><span className="text-[11px] font-semibold text-slate-400">This week&apos;s attendance</span><Check size={17} className="text-shamrock" /></div><p className="mt-5 text-4xl font-bold text-blue-950">92<span className="text-xl text-slate-300">%</span></p><p className="mt-1 text-[11px] text-shamrock">↑ 6% from last week</p></div></div><div className="mt-8 grid gap-5 lg:grid-cols-[1.25fr_.75fr]"><section className="rounded-2xl border border-slate-100 bg-white p-6 shadow-card sm:p-7"><div className="flex items-center justify-between"><div><h2 className="font-bold text-blue-950">Registrations by club</h2><p className="mt-1 text-xs text-slate-400">Current school year</p></div><button className="flex items-center gap-1 text-xs font-semibold text-slate-400">2026 / 2027 <ChevronDown size={14} /></button></div><div className="mt-8 space-y-5">{visibleClubs.map((club) => <div key={club.id}><div className="mb-2 flex justify-between gap-3 text-xs"><span className="truncate font-semibold text-slate-600">{club.name} <span className="font-normal text-slate-400">· {club.audience}</span></span><span className="font-bold text-blue-900">{club.members}</span></div><div className="h-2 overflow-hidden rounded-full bg-slate-100"><div className={`h-full rounded-full ${club.color === "violet" ? "bg-violet" : club.color === "orange" ? "bg-orange" : club.color === "yellow" ? "bg-bumblebee" : club.color === "green" ? "bg-shamrock" : "bg-blue-900"}`} style={{ width: `${club.members / max * 100}%` }} /></div></div>)}</div></section><section className="rounded-2xl border border-slate-100 bg-white p-6 shadow-card sm:p-7"><div className="flex items-start justify-between"><div><h2 className="font-bold text-blue-950">Quick attendance</h2><p className="mt-1 text-xs text-slate-400">Mark today&apos;s session</p></div><CalendarDays size={18} className="text-silver" /></div><div className="mt-6 space-y-2">{visibleClubs.slice(0, 5).map((club) => <Link key={club.id} href={`/admin/attendance/${club.id}`} className="group flex items-center justify-between rounded-xl bg-slate-50 p-3.5 transition hover:bg-[#f0f6fb]"><div><p className="text-xs font-bold text-blue-950">{club.name}</p><p className="mt-1 text-[10px] text-slate-400">{club.audience} · {club.meeting_day}</p></div><ArrowRight size={15} className="text-silver transition group-hover:translate-x-1 group-hover:text-blue-900" /></Link>)}</div><Link href="/admin/requests" className="mt-5 inline-block text-[11px] font-bold text-violet">Review change requests →</Link></section></div></div></main>;
}
